export const colors=['#188978','#5486c0','#c77d43','#8264aa','#b75b7c','#679343','#688896','#ad9950'];
export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const fmt=(x,digits=3)=>!Number.isFinite(x)?'Unavailable':x!==0&&Math.abs(x)<.001?x.toExponential(2):Math.abs(x)>1000?x.toLocaleString('en-US',{maximumFractionDigits:1}):Number(x.toPrecision(digits)).toString();
export function plot({series=[],xLabel='',yLabel='',title='',xDomain,yDomain,width=720,height=320,marker,logX=false,logY=false}){
 const left=57,right=20,top=26,bottom=47,w=width-left-right,h=height-top-bottom;
 const valid=series.flatMap(s=>s.points??[]).filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1])&&(!logX||p[0]>0)&&(!logY||p[1]>0));
 const tx=x=>logX?Math.log10(Math.max(x,1e-16)):x,ty=y=>logY?Math.log10(Math.max(y,1e-16)):y;
 const bounds=(axis,domain,transform)=>{if(domain)return domain.map(transform);const vals=valid.map(p=>transform(p[axis]));let lo=vals.length?Math.min(...vals):0,hi=vals.length?Math.max(...vals):1;if(lo===hi){lo-=1;hi+=1;}const pad=(hi-lo)*.08;return[lo-pad,hi+pad];};
 const [xmin,xmax]=bounds(0,xDomain,tx),[ymin,ymax]=bounds(1,yDomain,ty),sx=x=>left+(tx(x)-xmin)/(xmax-xmin)*w,sy=y=>top+h-(ty(y)-ymin)/(ymax-ymin)*h;
 let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title||`${yLabel} versus ${xLabel}`)}"><title>${esc(title||`${yLabel} versus ${xLabel}`)}</title>`;
 for(let i=0;i<=4;i++){const yy=top+h-i*h/4,v=ymin+i*(ymax-ymin)/4;svg+=`<line class="plot-grid" x1="${left}" y1="${yy}" x2="${left+w}" y2="${yy}"/><text class="plot-label" x="${left-9}" y="${yy+3}" text-anchor="end">${fmt(logY?10**v:v)}</text>`;const xx=left+i*w/4,u=xmin+i*(xmax-xmin)/4;svg+=`<text class="plot-label" x="${xx}" y="${top+h+20}" text-anchor="middle">${fmt(logX?10**u:u)}</text>`;}
 svg+=`<line class="plot-axis" x1="${left}" y1="${top+h}" x2="${left+w}" y2="${top+h}"/><text class="plot-axis-label" x="${left+w/2}" y="${height-7}" text-anchor="middle">${esc(xLabel)}${logX?' (log scale)':''}</text><text class="plot-axis-label" x="15" y="${top+h/2}" transform="rotate(-90 15 ${top+h/2})" text-anchor="middle">${esc(yLabel)}${logY?' (log scale)':''}</text>`;
 for(const s of series){const points=(s.points??[]).filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1])&&(!logX||p[0]>0)&&(!logY||p[1]>0)),color=s.color??colors[0];if(!points.length)continue;
  if(s.type==='band'){svg+=`<path d="${points.map((p,i)=>`${i?'L':'M'}${sx(p[0])},${sy(p[1])}`).join(' ')} Z" fill="${color}" opacity=".12"/>`;}
  else if(s.type==='bar'){const barWidth=Math.max(2,w/(points.length*1.5));points.forEach(p=>svg+=`<rect x="${sx(p[0])-barWidth/2}" y="${Math.min(sy(p[1]),sy(0))}" width="${barWidth}" height="${Math.abs(sy(p[1])-sy(0))}" fill="${color}" opacity=".75"><title>${esc(s.name)}: ${fmt(p[1])}</title></rect>`);}
  else{if(s.type!=='scatter')svg+=`<path d="${points.map((p,i)=>`${i?'L':'M'}${sx(p[0])},${sy(p[1])}`).join(' ')}" stroke="${color}" stroke-width="${s.strokeWidth??2}" fill="none" ${s.dashed?'stroke-dasharray="5 4"':''}/>`;if(s.type==='scatter'||s.dots)points.forEach((p,i)=>svg+=`<circle class="plot-point" cx="${sx(p[0])}" cy="${sy(p[1])}" r="${s.sizes?.[i]??s.radius??3}" fill="${color}" fill-opacity="${s.opacity??.75}" stroke="white" stroke-width=".7"><title>${esc(s.labels?.[i]??s.name??'Point')}: (${fmt(p[0])}, ${fmt(p[1])})</title></circle>`);}
 }
 if(Number.isFinite(marker))svg+=`<line x1="${sx(marker)}" x2="${sx(marker)}" y1="${top}" y2="${top+h}" stroke="#647b83" stroke-dasharray="3 4" opacity=".65"/>`;
 return svg+'</svg>';
}
export function legend(items){return`<div class="lab-legend">${items.map(([label,color])=>`<span class="legend-item"><i class="legend-swatch" style="--swatch:${color}"></i>${esc(label)}</span>`).join('')}</div>`;}
export function barPlot(rows,title,{maxRows=50}={}){const shown=rows.slice(0,maxRows),width=720,height=55+shown.length*26,left=200,right=95,range=width-left-right,max=Math.max(...shown.map(r=>r.value+r.interval||0),1e-16);let svg=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>`;shown.forEach((r,i)=>{const y=25+i*26,bar=range*Math.max(0,r.value)/max;svg+=`<text x="${left-10}" y="${y+4}" class="plot-label" text-anchor="end">${esc(r.label)}</text><rect x="${left}" y="${y-6}" width="${bar}" height="13" rx="2" fill="${r.color??colors[0]}" opacity=".8"><title>${esc(r.label)}: ${fmt(r.value)}${r.interval?` ± ${fmt(r.interval)}`:''}</title></rect><text x="${left+bar+8}" y="${y+4}" class="plot-label">${fmt(r.value)}</text>`;if(r.interval){const low=left+range*Math.max(0,r.value-r.interval)/max,high=left+range*(r.value+r.interval)/max;svg+=`<line x1="${low}" x2="${high}" y1="${y}" y2="${y}" stroke="#314959"/><line x1="${low}" x2="${low}" y1="${y-4}" y2="${y+4}" stroke="#314959"/><line x1="${high}" x2="${high}" y1="${y-4}" y2="${y+4}" stroke="#314959"/>`;}});return svg+`<text class="plot-axis-label" x="${left}" y="${height-5}">${esc(title)} · linear scale; bars start at zero</text></svg>`;}
